  Corollary ref_open_fail_absent_w :
    (length path <= 4095)%nat -> path <> [] -> openat_plain_name path = true -> fs_lookup fs0 path = None ->
    srealizes RSEGS scfg (mkCfg (mkst regs0 (0x38c2c : word) mem0 (seg_rom RSEGS)) model0)
