  #[using="sp0 Hplen LEN"] Lemma krange_lit : forall vals M (v : nat) (x lo hi : Z),
    vals_ev vals v = Z_to_bv 64 x -> (0 <= x < 2 ^ 64)%Z -> (lo <= x <= hi)%Z ->
    kentry_ok RSEGS (ENVb vals) M (KRange (EVar v) lo hi).
Proof.
