  #[using="uid hw rdraw Hva Hve Hvsp Hplen"] Lemma hiv_facts' : forall vals,
    vals_ev vals 3 = auxvp sp0 a0s path envv -> vals_ev vals 4 = rnd sp0 a0s path envv ->
