  Definition pf_rs (w : Z) : list (word * Z) :=
    [(Z_to_bv 64 (bv_unsigned sp0 - 208 - 1056), 1056%Z); (Z_to_bv 64 0xc6cc0, 4%Z); (Z_to_bv 64 0xc6ce8, 8%Z); (Z_to_bv 64 w, 2%Z)].
  Definition CPpf (w : Z) (a : Z) : Prop :=
    (~ (bv_unsigned sp0 - 208 - 1056 <= a < bv_unsigned sp0 - 208) /\ ~ (0xc6cc0 <= a < 0xc6cc4) /\ ~ (0xc6ce8 <= a < 0xc6cf0) /\ ~ (w <= a < w + 2))%Z.
  Definition SCpf (a : Z) : Prop := (bv_unsigned sp0 - 208 - 1056 <= a < bv_unsigned sp0 - 208)%Z.

