From Ltac2 Require Import Ltac2.
Set Default Proof Mode "Classic".
Ltac2 rds2_prove (t : constr) : constr := constr:(ltac2:(ltac1:(repeat match goal with H : _ |- _ => clear H end; intros; lia)) : $t).
Ltac2 rec rds2_sub (f : constr -> constr option) (c : constr) : bool * constr :=
  match f c with
  | Some c' => (true, c')
  | None =>
    let mk := Constr.Unsafe.make in
    let sb b :=
      let (ch, t) := rds2_sub f (Constr.Binder.type b) in
      if ch then (true, Constr.Binder.unsafe_make (Constr.Binder.name b) (Constr.Binder.relevance b) t) else (false, b) in
    let arr a :=
      let ch := { contents := false } in
      let a' := Array.map (fun x => let (cx, x') := rds2_sub f x in (if cx then ch.(contents) := true else ()); x') a in
      (ch.(contents), a') in
    let barr a :=
      let ch := { contents := false } in
      let a' := Array.map (fun x => let (cx, x') := sb x in (if cx then ch.(contents) := true else ()); x') a in
      (ch.(contents), a') in
    match Constr.Unsafe.kind c with
    | Constr.Unsafe.LetIn b v body =>
      let (c1, b') := sb b in let (c2, v') := rds2_sub f v in let (c3, body') := rds2_sub f body in
      if Bool.or c1 (Bool.or c2 c3) then (true, mk (Constr.Unsafe.LetIn b' v' body')) else (false, c)
    | Constr.Unsafe.Lambda b body =>
      let (c1, b') := sb b in let (c2, body') := rds2_sub f body in
      if Bool.or c1 c2 then (true, mk (Constr.Unsafe.Lambda b' body')) else (false, c)
    | Constr.Unsafe.Prod b body =>
      let (c1, b') := sb b in let (c2, body') := rds2_sub f body in
      if Bool.or c1 c2 then (true, mk (Constr.Unsafe.Prod b' body')) else (false, c)
    | Constr.Unsafe.App h args =>
      let (c1, h') := rds2_sub f h in let (c2, args') := arr args in
      if Bool.or c1 c2 then (true, mk (Constr.Unsafe.App h' args')) else (false, c)
    | Constr.Unsafe.Cast c1 k t =>
      let (x1, c1') := rds2_sub f c1 in let (x2, t') := rds2_sub f t in
      if Bool.or x1 x2 then (true, mk (Constr.Unsafe.Cast c1' k t')) else (false, c)
    | Constr.Unsafe.Case ci (rt, rr) iv scr brs =>
      let (c1, rt') := rds2_sub f rt in let (c2, scr') := rds2_sub f scr in let (c3, brs') := arr brs in
      if Bool.or c1 (Bool.or c2 c3) then (true, mk (Constr.Unsafe.Case ci (rt', rr) iv scr' brs')) else (false, c)
    | Constr.Unsafe.Fix recs i bs bds =>
      let (c1, bs') := barr bs in let (c2, bds') := arr bds in
      if Bool.or c1 c2 then (true, mk (Constr.Unsafe.Fix recs i bs' bds')) else (false, c)
    | Constr.Unsafe.CoFix i bs bds =>
      let (c1, bs') := barr bs in let (c2, bds') := arr bds in
      if Bool.or c1 c2 then (true, mk (Constr.Unsafe.CoFix i bs' bds')) else (false, c)
    | Constr.Unsafe.Proj p r c1 =>
      let (x1, c1') := rds2_sub f c1 in
      if x1 then (true, mk (Constr.Unsafe.Proj p r c1')) else (false, c)
    | _ => (false, c)
    end
  end.
Ltac2 rec rds2_prefix (c : constr) (a : constr) (b : constr) : constr option :=
  match Constr.Unsafe.kind c with
  | Constr.Unsafe.App h cargs =>
    match Constr.Unsafe.kind a with
    | Constr.Unsafe.App ha aargs =>
      let n := Array.length aargs in
      if Bool.and (Int.lt n (Array.length cargs)) (Constr.equal h ha) then
        let rec same i := if Int.ge i n then true else if Constr.equal (Array.get aargs i) (Array.get cargs i) then same (Int.add i 1) else false in
        if same 0 then
          match Constr.Unsafe.kind b with
          | Constr.Unsafe.App hb bargs =>
            if Int.equal (Array.length bargs) n then
              let rec pairs i :=
                if Int.ge i n then []
                else let x := Array.get aargs i in let y := Array.get bargs i in
                     if Constr.equal x y then pairs (Int.add i 1) else (x, y) :: pairs (Int.add i 1) in
              let ps := pairs 0 in
              let rest := Array.map (fun x => let (_, x') := rds2_sub (rds2_lit ps) x in x')
                            (Array.sub cargs n (Int.sub (Array.length cargs) n)) in
              Some (Constr.Unsafe.make (Constr.Unsafe.App hb (Array.append bargs rest)))
            else None
          | _ => None
          end
        else None
      else None
    | _ => None
    end
  | _ => None
  end
with rds2_lit (subs : (constr * constr) list) (c : constr) : constr option :=
  match subs with
  | [] => None
  | (a, b) :: r =>
    if Constr.equal c a then Some b
    else match rds2_prefix c a b with Some x => Some x | None => rds2_lit r c end
  end.
Ltac2 rec rds2_tsub (subs : (constr * constr) list) (c : constr) : bool * constr :=
  let mk := Constr.Unsafe.make in
  let arr a :=
    let ch := { contents := false } in
    let a' := Array.map (fun x => let (cx, x') := rds2_tsub subs x in (if cx then ch.(contents) := true else ()); x') a in
    (ch.(contents), a') in
  match Constr.Unsafe.kind c with
  | Constr.Unsafe.LetIn b v body =>
    let (cb, body') := rds2_tsub subs body in
    let t := Constr.Binder.type b in
    let is_arith := match Constr.Binder.name b with Some id => Ident.equal id @__arith | None => false end in
    let (ct, t') := if is_arith then rds2_sub (rds2_lit subs) t else (false, t) in
    if ct then
      if Constr.Unsafe.closedn 0 t' then
        (true, mk (Constr.Unsafe.LetIn (Constr.Binder.unsafe_make (Constr.Binder.name b) (Constr.Binder.relevance b) t') (rds2_prove t') body'))
      else Control.throw (Tactic_failure (Some (Message.of_string "rds2_tsub: __arith type not closed")))
    else
      let (cv, v') := rds2_tsub subs v in
      if Bool.or cv cb then (true, mk (Constr.Unsafe.LetIn b v' body')) else (false, c)
  | Constr.Unsafe.Lambda b body =>
    let (cb, body') := rds2_tsub subs body in
    if cb then (true, mk (Constr.Unsafe.Lambda b body')) else (false, c)
  | Constr.Unsafe.App f args =>
    let (cf, f') := rds2_tsub subs f in
    let (ca, args') := arr args in
    if Bool.or cf ca then (true, mk (Constr.Unsafe.App f' args')) else (false, c)
  | Constr.Unsafe.Cast c1 k t =>
    let (c1c, c1') := rds2_tsub subs c1 in
    if c1c then (true, mk (Constr.Unsafe.Cast c1' k t)) else (false, c)
  | Constr.Unsafe.Case ci rt iv scr brs =>
    let (cs, scr') := rds2_tsub subs scr in
    let (cb, brs') := arr brs in
    if Bool.or cs cb then (true, mk (Constr.Unsafe.Case ci rt iv scr' brs')) else (false, c)
  | Constr.Unsafe.Fix recs i bs bds =>
    let (cb, bds') := arr bds in
    if cb then (true, mk (Constr.Unsafe.Fix recs i bs bds')) else (false, c)
  | _ => (false, c)
  end.
Ltac2 rec rds2_look (env : constr option list) (n : int) : constr option :=
  match env with [] => None | x :: r => if Int.equal n 0 then x else rds2_look r (Int.sub n 1) end.
Ltac2 rec rds2_drop (env : constr option list) (n : int) : constr option list :=
  if Int.equal n 0 then env else match env with [] => [] | _ :: r => rds2_drop r (Int.sub n 1) end.
Ltac2 rec rds2_eqv (env : constr option list) (t : constr) (a : constr) : bool :=
  match Constr.Unsafe.kind t with
  | Constr.Unsafe.Rel i =>
    match rds2_look env (Int.sub i 1) with Some v => rds2_eqv (rds2_drop env i) v a | None => false end
  | Constr.Unsafe.App f args =>
    match Constr.Unsafe.kind a with
    | Constr.Unsafe.App fa aargs =>
      if Bool.and (Int.equal (Array.length args) (Array.length aargs)) (rds2_eqv env f fa) then
        let rec all i := if Int.ge i (Array.length args) then true
                         else if rds2_eqv env (Array.get args i) (Array.get aargs i) then all (Int.add i 1) else false in
        all 0
      else false
    | _ => false
    end
  | _ => Constr.equal t a
  end.
Ltac2 rec rds2_close (env : constr option list) (t : constr) : constr option :=
  match Constr.Unsafe.kind t with
  | Constr.Unsafe.Rel i =>
    match rds2_look env (Int.sub i 1) with Some v => rds2_close (rds2_drop env i) v | None => None end
  | Constr.Unsafe.App f args =>
    match rds2_close env f with
    | Some f' =>
      let ok := { contents := true } in
      let args' := Array.map (fun x => match rds2_close env x with Some y => y | None => (ok.(contents) := false); x end) args in
      if ok.(contents) then Some (Constr.Unsafe.make (Constr.Unsafe.App f' args')) else None
    | None => None
    end
  | Constr.Unsafe.Cast c1 _ _ => rds2_close env c1
  | Constr.Unsafe.Constant _ _ => Some t
  | Constr.Unsafe.Constructor _ _ => Some t
  | Constr.Unsafe.Ind _ _ => Some t
  | Constr.Unsafe.Var _ => Some t
  | _ => None
  end.
Ltac2 rds2_nth_shift (env : constr option list) (args : constr array) : int :=
  match (rds2_close env (Array.get args 3), rds2_close env (Array.get args 4), rds2_close env (Array.get args 5)) with
  | (Some kn, Some i, Some k) =>
    let kv := Std.eval_vm None k in
    let ty := match Constr.Unsafe.kind (Constr.type kn) with Constr.Unsafe.App _ a => Array.get a 0 | _ => Control.throw (Tactic_failure (Some (Message.of_string "rds2_nth_shift: list type"))) end in
    let ok_at n := match Constr.Unsafe.kind (Std.eval_vm None (Constr.Unsafe.make (Constr.Unsafe.App constr:(@nth_error) (Array.of_list [ty; kn; n])))) with
      | Constr.Unsafe.App _ a => if Int.equal (Array.length a) 2 then Constr.equal (Array.get a 1) kv else false
      | _ => false end in
    let s1 := Constr.Unsafe.make (Constr.Unsafe.App constr:(S) (Array.of_list [i])) in
    if ok_at i then 0 else if ok_at s1 then 1
    else if ok_at (Constr.Unsafe.make (Constr.Unsafe.App constr:(S) (Array.of_list [s1]))) then 2 else 0
  | _ => 0
  end.
Ltac2 rec rds2_nones (n : int) (env : constr option list) : constr option list :=
  if Int.le n 0 then env else rds2_nones (Int.sub n 1) (None :: env).
Ltac2 rec rds2_split (spl : (constr * constr * constr) list) (nh : constr list) (env : constr option list) (c : constr) : bool * constr :=
  let mk := Constr.Unsafe.make in
  let sb env b :=
    let (ch, t) := rds2_split spl nh env (Constr.Binder.type b) in
    if ch then (true, Constr.Binder.unsafe_make (Constr.Binder.name b) (Constr.Binder.relevance b) t) else (false, b) in
  let arr env a :=
    let ch := { contents := false } in
    let a' := Array.map (fun x => let (cx, x') := rds2_split spl nh env x in (if cx then ch.(contents) := true else ()); x') a in
    (ch.(contents), a') in
  match Constr.Unsafe.kind c with
  | Constr.Unsafe.LetIn b v body =>
    let (c1, b') := sb env b in let (c2, v') := rds2_split spl nh env v in
    let (c3, body') := rds2_split spl nh (Some v' :: env) body in
    if Bool.or c1 (Bool.or c2 c3) then (true, mk (Constr.Unsafe.LetIn b' v' body')) else (false, c)
  | Constr.Unsafe.Lambda b body =>
    let (c1, b') := sb env b in let (c2, body') := rds2_split spl nh (None :: env) body in
    if Bool.or c1 c2 then (true, mk (Constr.Unsafe.Lambda b' body')) else (false, c)
  | Constr.Unsafe.Prod b body =>
    let (c1, b') := sb env b in let (c2, body') := rds2_split spl nh (None :: env) body in
    if Bool.or c1 c2 then (true, mk (Constr.Unsafe.Prod b' body')) else (false, c)
  | Constr.Unsafe.App h args =>
    let hit := if Bool.and (Int.equal (Array.length args) 3) (Constr.equal h constr:(@cons)) then
        List.find_opt (fun (a, _, _) => rds2_eqv env (Array.get args 1) a) spl else None in
    let (c1, h') := rds2_split spl nh env h in let (c2, args') := arr env args in
    let nth := if Bool.and (Int.equal (Array.length args) 8) (List.exist (fun x => Constr.equal h x) nh) then rds2_nth_shift env args' else 0 in
    let args' := if Int.equal nth 0 then args' else
      let i := Array.get args' 4 in
      let rec sk n x := if Int.equal n 0 then x else sk (Int.sub n 1) (mk (Constr.Unsafe.App constr:(S) (Array.of_list [x]))) in
      let i' := sk nth i in
      Array.mapi (fun j x => if Int.equal j 4 then i' else if Int.equal j 7 then (let (_, x') := rds2_sub (rds2_lit [(i, i')]) x in x') else x) args' in
    let c2 := Bool.or c2 (Bool.neg (Int.equal nth 0)) in
    match hit with
    | Some (_, k1, k2) =>
      let ty := Array.get args' 0 in
      (true, mk (Constr.Unsafe.App h' (Array.of_list [ty; k1; mk (Constr.Unsafe.App h' (Array.of_list [ty; k2; Array.get args' 2]))])))
    | None => if Bool.or c1 c2 then (true, mk (Constr.Unsafe.App h' args')) else (false, c)
    end
  | Constr.Unsafe.Cast c1 k t =>
    let (x1, c1') := rds2_split spl nh env c1 in let (x2, t') := rds2_split spl nh env t in
    if Bool.or x1 x2 then (true, mk (Constr.Unsafe.Cast c1' k t')) else (false, c)
  | Constr.Unsafe.Case ci (rt, rr) iv scr brs =>
    let (c1, rt') := rds2_split spl nh env rt in let (c2, scr') := rds2_split spl nh env scr in let (c3, brs') := arr env brs in
    if Bool.or c1 (Bool.or c2 c3) then (true, mk (Constr.Unsafe.Case ci (rt', rr) iv scr' brs')) else (false, c)
  | Constr.Unsafe.Fix recs i bs bds =>
    let (c2, bds') := arr (rds2_nones (Array.length bs) env) bds in
    if c2 then (true, mk (Constr.Unsafe.Fix recs i bs bds')) else (false, c)
  | Constr.Unsafe.Proj p r c1 =>
    let (x1, c1') := rds2_split spl nh env c1 in
    if x1 then (true, mk (Constr.Unsafe.Proj p r c1')) else (false, c)
  | _ => (false, c)
  end.
Ltac2 rds2_runf (subs : (constr * constr) list) (spl : (constr * constr * constr) list) (nh : constr list) (tab : string) (secs : string list) (s : string) : unit :=
  KReplay.kr_revert ();
  let ph := { contents := [] } in
  let c := KReplay.decode_ph (Some ph) tab (KReplay.kr_secs secs) s in
  let hs := { contents := false } in
  let ht := { contents := false } in
  let fx x :=
    let (c1, x1) := match spl with [] => (false, x) | _ => rds2_split spl nh [] x end in
    let (c2, x2) := match subs with [] => (false, x1) | _ => rds2_tsub subs x1 end in
    (if c1 then hs.(contents) := true else ()); (if c2 then ht.(contents) := true else ()); x2 in
  Std.exact_no_check (fx c);
  List.iter (fun (e, b) => Control.new_goal e; Control.enter (fun () => Std.exact_no_check (fx b))) (ph.(contents));
  (match spl with [] => () | _ => if hs.(contents) then () else Control.throw (Tactic_failure (Some (Message.of_string "rds2_runf: no list entry matched"))) end);
  (match subs with [] => () | _ => if ht.(contents) then () else Control.throw (Tactic_failure (Some (Message.of_string "rds2_runf: no __arith type matched"))) end).
