(* [comment removed for export] *)
Definition re_ivs : list (Z * Z) :=
  [(0x10000,0xc6dd0); (0xc6dd1,0xc6e19); (0xd6e19,0xd8780); (0xf8858,0xf8878); (0xd87b4,0xd8800); (0xd8808,0xd8820);
   (0xd8828,0xd8840); (0xd8850,0xd8860); (0xd8868,0xd88d8); (0xf8890,0xf8ac0); (0xf8ac8,0xf8ad0); (0xf8ae1,0xf8ae8);
