Lemma t_body_ok : forall data fs, Z.of_nat (length data) < MAX_INPUT -> 6 + CFG data <= Z.of_nat (length data) ->
  t_body data fs = t_emit (W 1 (zero_lines (Z.to_nat (CALLS data)))) (t_exit (exit_code 0) fs).
Proof.
